INSERT INTO sat_questions (question_id, external_id, vault_id, disclosed_item_id, source, program, test_type, test_type_desc, domain, primary_class_cd, skill_cd, skill_desc, difficulty, score_band_range_cd, question_type, stimulus_html, stem_html, answer_options, correct_answer, answer_keys, rationale_html, correct_answer_extracted_from_rationale, image_count, parent_template_name, parent_template_id, template_cluster_id, template_cluster_name, origin, position, answer_style, section, raw_payload, created_date, updated_date) VALUES
    ($SATQ$e62241b7$SATQ$, $SATQ$3bf90a30-ea0e-4762-adb2-a5e07db0fb4d$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>What is the correct pronunciation of Kiribati? In the Gilbertese language spoken by residents of the island nation, the letter combination -ti makes the -s sound; as a result, the country&rsquo;s name <span aria-hidden="true">______</span><span class="sr-only">blank</span> pronounced &ldquo;Kiribas.&rdquo;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"ff237006-8c1a-46f5-afd2-61ae81ef3374","content":"<p>are</p>"},{"id":"6b90b181-e3eb-4ff1-97d5-c82f84e78261","content":"<p>have been</p>"},{"id":"8dd2c271-cd07-43b4-a11f-01bc86ad05aa","content":"<p>are being</p>"},{"id":"cff8b8a3-a073-40d6-afe3-4e40ace314fc","content":"<p>is</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["cff8b8a3-a073-40d6-afe3-4e40ace314fc"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb "is" agrees in number with the singular subject "the country&rsquo;s name."</p><p>Choice A is incorrect because the plural verb "are" doesn&rsquo;t agree in number with the singular subject "the country&rsquo;s name." Choice B is incorrect because the plural verb "have been" doesn&rsquo;t agree in number with the singular subject "the country&rsquo;s name." Choice C is incorrect because the plural verb "are being" doesn&rsquo;t agree in number with the singular subject "the country&rsquo;s name."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e62241b7","external_id":"3bf90a30-ea0e-4762-adb2-a5e07db0fb4d","vaultid":null,"uId":"05a081a0-1679-4ecb-a3ed-56fd171077f5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>What is the correct pronunciation of Kiribati? In the Gilbertese language spoken by residents of the island nation, the letter combination -ti makes the -s sound; as a result, the country&rsquo;s name <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> pronounced &ldquo;Kiribas.&rdquo;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"ff237006-8c1a-46f5-afd2-61ae81ef3374","content":"<p>are</p>"},{"id":"6b90b181-e3eb-4ff1-97d5-c82f84e78261","content":"<p>have been</p>"},{"id":"8dd2c271-cd07-43b4-a11f-01bc86ad05aa","content":"<p>are being</p>"},{"id":"cff8b8a3-a073-40d6-afe3-4e40ace314fc","content":"<p>is</p>"}],"keys":["cff8b8a3-a073-40d6-afe3-4e40ace314fc"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The singular verb \"is\" agrees in number with the singular subject \"the country&rsquo;s name.\"</p><p>Choice A is incorrect because the plural verb \"are\" doesn&rsquo;t agree in number with the singular subject \"the country&rsquo;s name.\" Choice B is incorrect because the plural verb \"have been\" doesn&rsquo;t agree in number with the singular subject \"the country&rsquo;s name.\" Choice C is incorrect because the plural verb \"are being\" doesn&rsquo;t agree in number with the singular subject \"the country&rsquo;s name.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$e6f2dba6$SATQ$, $SATQ$84666224-5c68-4c5f-a22d-c52e9a707389$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>According to the traditional RYB (red-yellow-blue) color model, yellow is a complementary color to purple. However, yellow <span aria-hidden="true">______</span><span class="sr-only">blank</span> considered complementary to blue in modern color theory.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"377a4b69-e5a8-430a-b1e5-2befddb809ff","content":"<p>is</p>"},{"id":"e7738696-303f-4a30-82ac-372a182c80f2","content":"<p>having been</p>"},{"id":"98e32d1f-66a2-4d2d-80dd-33c2f6c4a3b7","content":"<p>to be</p>"},{"id":"ae99b628-a14a-4356-b580-52abd74211b6","content":"<p>being</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["377a4b69-e5a8-430a-b1e5-2befddb809ff"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, "yellow"), and this choice supplies the present tense verb "is considered" to indicate that yellow is considered a complementary color to blue in modern color theory.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle "having been considered" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive "to be considered" doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite participle "being considered" doesn&rsquo;t supply the main clause with a finite verb.</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e6f2dba6","external_id":"84666224-5c68-4c5f-a22d-c52e9a707389","vaultid":null,"uId":"1c237574-da42-4621-9f0d-558ddd463593","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>According to the traditional RYB (red-yellow-blue) color model, yellow is a complementary color to purple. However, yellow <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> considered complementary to blue in modern color theory.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"377a4b69-e5a8-430a-b1e5-2befddb809ff","content":"<p>is</p>"},{"id":"e7738696-303f-4a30-82ac-372a182c80f2","content":"<p>having been</p>"},{"id":"98e32d1f-66a2-4d2d-80dd-33c2f6c4a3b7","content":"<p>to be</p>"},{"id":"ae99b628-a14a-4356-b580-52abd74211b6","content":"<p>being</p>"}],"keys":["377a4b69-e5a8-430a-b1e5-2befddb809ff"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of verb forms within a sentence. A main clause requires a finite (tensed) verb to perform the action of the subject (in this case, \"yellow\"), and this choice supplies the present tense verb \"is considered\" to indicate that yellow is considered a complementary color to blue in modern color theory.</p><p>Choice B is incorrect because it results in an ungrammatical sentence. The nonfinite participle \"having been considered\" doesn&rsquo;t supply the main clause with a finite verb. Choice C is incorrect because it results in an ungrammatical sentence. The nonfinite to-infinitive \"to be considered\" doesn&rsquo;t supply the main clause with a finite verb. Choice D is incorrect because it results in an ungrammatical sentence. The nonfinite participle \"being considered\" doesn&rsquo;t supply the main clause with a finite verb.</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$e76e74e8$SATQ$, $SATQ$6bdebc9a-4dfe-43f2-8b13-576a2c99847f$SATQ$::uuid, $SATQ$c7b7a0e7-005c-4d52-8bf4-58bc0ef45246$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 6, $SATQ$mcq$SATQ$, $SATQ$<p>Over twenty years ago, in a landmark experiment in the psychology of choice, professor Sheena Iyengar set up a jam-tasting booth at a grocery store. The number of jams available for tasting <span aria-hidden="true">______</span><span class="sr-only">blank</span> some shoppers had twenty-four different options, others only six. Interestingly, the shoppers with fewer jams to choose from purchased more jam.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"f37e2d79-1294-4f8f-bbb6-a5e4ce8ff825","content":"<p>varied:</p>"},{"id":"f94bc372-5dca-4d35-842d-e2883dee191a","content":"<p>varied,&nbsp;</p>"},{"id":"ed6efe68-7230-4fcd-86c1-734e373fef70","content":"<p>varied, while</p>"},{"id":"495c908c-3a74-4156-a233-f8de1df99888","content":"<p>varied while</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["f37e2d79-1294-4f8f-bbb6-a5e4ce8ff825"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon is used in a conventional way to introduce the following description of how the number of jams available varied.&nbsp;</p><p>Choice B is incorrect because it creates a comma splice. A comma can&rsquo;t be used in this way to join two main clauses (&ldquo;the number&hellip;varied&rdquo; and &ldquo;some&hellip;six&rdquo;). Choice C is incorrect because it results in an illogical and confusing sentence. Using the conjunction &ldquo;while&rdquo; to join the main clause (&ldquo;the number&hellip;varied&rdquo;) with the following clause&rsquo;s description of the number of jams available suggests that the variation in the number of jams is in contrast to some shoppers having twenty-four options. Choice D is incorrect because it results in an illogical and confusing sentence. Using &ldquo;while&rdquo; in this way suggests that the number of jams available varied during the time in which some shoppers had twenty-four options and others had six. The sentence makes clear, however, that what follows &ldquo;varied&rdquo; is a description of the variation, not a separate, simultaneous occurrence. </p>$SATQ$, false, 0, $SATQ$OSP-709-SEC$SATQ$, $SATQ$$SATQ$, $SATQ$a2008fff-6eea-4f77-8984-b45ae1e8582c$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"e76e74e8","external_id":"6bdebc9a-4dfe-43f2-8b13-576a2c99847f","vaultid":"c7b7a0e7-005c-4d52-8bf4-58bc0ef45246","uId":"418674cc-5372-4384-af8e-0a87bbeac1e4","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":6,"type":"mcq","stimulus":"<p>Over twenty years ago, in a landmark experiment in the psychology of choice, professor Sheena Iyengar set up a jam-tasting booth at a grocery store. The number of jams available for tasting <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> some shoppers had twenty-four different options, others only six. Interestingly, the shoppers with fewer jams to choose from purchased more jam.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"f37e2d79-1294-4f8f-bbb6-a5e4ce8ff825","content":"<p>varied:</p>"},{"id":"f94bc372-5dca-4d35-842d-e2883dee191a","content":"<p>varied,&nbsp;</p>"},{"id":"ed6efe68-7230-4fcd-86c1-734e373fef70","content":"<p>varied, while</p>"},{"id":"495c908c-3a74-4156-a233-f8de1df99888","content":"<p>varied while</p>"}],"keys":["f37e2d79-1294-4f8f-bbb6-a5e4ce8ff825"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon is used in a conventional way to introduce the following description of how the number of jams available varied.&nbsp;</p><p>Choice B is incorrect because it creates a comma splice. A comma can&rsquo;t be used in this way to join two main clauses (&ldquo;the number&hellip;varied&rdquo; and &ldquo;some&hellip;six&rdquo;). Choice C is incorrect because it results in an illogical and confusing sentence. Using the conjunction &ldquo;while&rdquo; to join the main clause (&ldquo;the number&hellip;varied&rdquo;) with the following clause&rsquo;s description of the number of jams available suggests that the variation in the number of jams is in contrast to some shoppers having twenty-four options. Choice D is incorrect because it results in an illogical and confusing sentence. Using &ldquo;while&rdquo; in this way suggests that the number of jams available varied during the time in which some shoppers had twenty-four options and others had six. The sentence makes clear, however, that what follows &ldquo;varied&rdquo; is a description of the variation, not a separate, simultaneous occurrence. </p>","parenttemplatename":"OSP-709-SEC","parenttemplateid":"","templateclusterid":"a2008fff-6eea-4f77-8984-b45ae1e8582c","templateclustername":"","origin":"proteus","position":"0","createDate":1691007959347,"updateDate":1691007959347}$SATQ$::jsonb, 1691007959347, 1691007959347),
    ($SATQ$e8926747$SATQ$, $SATQ$8762455f-8d5b-4463-a813-95381510eaea$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>Eighteen letters written by Louisa May Alcott, author of the popular novel <em>Little Women</em> (<span data-ssml-say-as="date">1868</span>), can be found at the New York Historical Society. <span aria-hidden="true">______</span><span class="sr-only">blank</span> letters demonstrate Alcott&rsquo;s keen business sense in her interactions with publishers.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"552f512c-3a61-4fd1-b395-a83f7c92df30","content":"<p>One</p>"},{"id":"985e9a2c-fa76-4000-baef-ac6a76b6f689","content":"<p>That</p>"},{"id":"da6c8379-f583-44fb-8081-bd07abccf9b7","content":"<p>This</p>"},{"id":"b1e15749-cd45-4fbd-8be2-6b3183850605","content":"<p>These</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["b1e15749-cd45-4fbd-8be2-6b3183850605"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is the use of determiners in a sentence. The plural determiner "these" agrees in number with the plural noun "letters" that it modifies. This choice clearly indicates that the letters demonstrate Alcott&rsquo;s business sense.</p><p>Choice A is incorrect because the singular determiner "one" doesn&rsquo;t agree in number with the plural noun "letters." Choice B is incorrect because the singular determiner "that" doesn&rsquo;t agree in number with the plural noun "letters." Choice C is incorrect because the singular determiner "this" doesn&rsquo;t agree in number with the plural noun "letters."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e8926747","external_id":"8762455f-8d5b-4463-a813-95381510eaea","vaultid":null,"uId":"55545efd-0de8-4466-a00a-321cc830bcc5","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>Eighteen letters written by Louisa May Alcott, author of the popular novel <em>Little Women</em> (<span data-ssml-say-as=\"date\">1868</span>), can be found at the New York Historical Society. <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> letters demonstrate Alcott&rsquo;s keen business sense in her interactions with publishers.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"552f512c-3a61-4fd1-b395-a83f7c92df30","content":"<p>One</p>"},{"id":"985e9a2c-fa76-4000-baef-ac6a76b6f689","content":"<p>That</p>"},{"id":"da6c8379-f583-44fb-8081-bd07abccf9b7","content":"<p>This</p>"},{"id":"b1e15749-cd45-4fbd-8be2-6b3183850605","content":"<p>These</p>"}],"keys":["b1e15749-cd45-4fbd-8be2-6b3183850605"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is the use of determiners in a sentence. The plural determiner \"these\" agrees in number with the plural noun \"letters\" that it modifies. This choice clearly indicates that the letters demonstrate Alcott&rsquo;s business sense.</p><p>Choice A is incorrect because the singular determiner \"one\" doesn&rsquo;t agree in number with the plural noun \"letters.\" Choice B is incorrect because the singular determiner \"that\" doesn&rsquo;t agree in number with the plural noun \"letters.\" Choice C is incorrect because the singular determiner \"this\" doesn&rsquo;t agree in number with the plural noun \"letters.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1743430669211,"updateDate":1743430669211}$SATQ$::jsonb, 1743430669211, 1743430669211),
    ($SATQ$e92a7ad3$SATQ$, $SATQ$18630e41-b176-43e2-a994-3e994b4f977c$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$E$SATQ$, 2, $SATQ$mcq$SATQ$, $SATQ$<p>In the Inca Empire (1438&ndash;1533), ayllus <span aria-hidden="true">______</span><span class="sr-only">blank</span> family clans that ranged in size from small groups to thousands of people.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"b33b6761-f576-4867-95d5-84f055e523e5","content":"<p>is</p>"},{"id":"2b3f41a9-2092-42ad-801c-f55ac6d7d535","content":"<p>was</p>"},{"id":"614729d8-e6f1-4ab7-b1ef-7a5c00f62c34","content":"<p>has been</p>"},{"id":"fd8fdf78-b8e5-4b18-a7d4-b0858fb6b391","content":"<p>were</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["fd8fdf78-b8e5-4b18-a7d4-b0858fb6b391"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb "were" agrees in number with the plural subject "ayllus," which are described as plural "family clans."</p><p>Choice A is incorrect because the singular verb "is" doesn&rsquo;t agree in number with the plural subject "ayllus." Choice B is incorrect because the singular verb "was" doesn&rsquo;t agree in number with the plural subject "ayllus." Choice C is incorrect because the singular verb "has been" doesn&rsquo;t agree in number with the plural subject "ayllus."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e92a7ad3","external_id":"18630e41-b176-43e2-a994-3e994b4f977c","vaultid":null,"uId":"dbebf9cf-40ac-4f3c-90ad-c6dd5cd2d9af","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"FSS","skill_desc":"Form, Structure, and Sense","difficulty":"E","score_band_range_cd":2,"type":"mcq","stimulus":"<p>In the Inca Empire (1438&ndash;1533), ayllus <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> family clans that ranged in size from small groups to thousands of people.</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"b33b6761-f576-4867-95d5-84f055e523e5","content":"<p>is</p>"},{"id":"2b3f41a9-2092-42ad-801c-f55ac6d7d535","content":"<p>was</p>"},{"id":"614729d8-e6f1-4ab7-b1ef-7a5c00f62c34","content":"<p>has been</p>"},{"id":"fd8fdf78-b8e5-4b18-a7d4-b0858fb6b391","content":"<p>were</p>"}],"keys":["fd8fdf78-b8e5-4b18-a7d4-b0858fb6b391"],"correct_answer":["D"],"rationale":"<p>Choice D is the best answer. The convention being tested is subject-verb agreement. The plural verb \"were\" agrees in number with the plural subject \"ayllus,\" which are described as plural \"family clans.\"</p><p>Choice A is incorrect because the singular verb \"is\" doesn&rsquo;t agree in number with the plural subject \"ayllus.\" Choice B is incorrect because the singular verb \"was\" doesn&rsquo;t agree in number with the plural subject \"ayllus.\" Choice C is incorrect because the singular verb \"has been\" doesn&rsquo;t agree in number with the plural subject \"ayllus.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323051,"updateDate":1730147323051}$SATQ$::jsonb, 1730147323051, 1730147323051),
    ($SATQ$e9aee0d8$SATQ$, $SATQ$ce93882d-e9b3-4571-9397-90d1592b6836$SATQ$::uuid, NULL, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$BOU$SATQ$, $SATQ$Boundaries$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>On November 2, 1772, amid rising tensions with Great Britain, Boston colonists formed the Boston Committee of Correspondence. By 1774, what had started as a local means of mobilizing support for the Patriot cause had grown into something far more <span aria-hidden="true">______</span><span class="sr-only">blank</span> network of such committees that, facilitating communication among the colonies, helped lay the groundwork for the Continental Congress. &nbsp;</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"a57d7686-92df-46d2-9f6c-a69b4da14c70","content":"<p>extensive: a&nbsp;</p>"},{"id":"d73f6575-64ca-49ef-938d-0233b96c79e9","content":"<p>extensive; a</p>"},{"id":"22dbf2e5-6e7d-4e54-9a9e-a237bb07b861","content":"<p>extensive, it was a &nbsp;</p>"},{"id":"a8cdb39e-97da-4db2-9afd-fb459d19599b","content":"<p>extensive. A&nbsp;</p>"}]$SATQ$::jsonb, $SATQ$["A"]$SATQ$::jsonb, $SATQ$["a57d7686-92df-46d2-9f6c-a69b4da14c70"]$SATQ$::jsonb, $SATQ$<p>Choice A is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon is correctly used to introduce the following explanation of what the Patriot cause had grown into by 1774.</p><p>Choice B is incorrect because a semicolon can&rsquo;t be used in this way to join the main clause ("what&hellip;extensive") and the supplementary element  ("a network&hellip;Congress"). A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce an element that explains or amplifies the information in the preceding clause, making the colon the better choice in this context. Choice C is incorrect because it results in a comma splice. The addition of the pronoun and verb "it was" forms the start of a new main clause in the sentence, and a comma can&rsquo;t be used in this way to mark the boundary between two main clauses. Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with "a network."</p>$SATQ$, false, 0, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, $SATQ${"questionId":"e9aee0d8","external_id":"ce93882d-e9b3-4571-9397-90d1592b6836","vaultid":null,"uId":"5678f389-a7eb-49dc-bc3f-ceb8acfb165a","program":"SAT","test_type":1,"test_type_desc":"Reading and Writing","primary_class_cd":"SEC","domain":"Standard English Conventions","skill_cd":"BOU","skill_desc":"Boundaries","difficulty":"H","score_band_range_cd":7,"type":"mcq","stimulus":"<p>On November 2, 1772, amid rising tensions with Great Britain, Boston colonists formed the Boston Committee of Correspondence. By 1774, what had started as a local means of mobilizing support for the Patriot cause had grown into something far more <span aria-hidden=\"true\">______</span><span class=\"sr-only\">blank</span> network of such committees that, facilitating communication among the colonies, helped lay the groundwork for the Continental Congress. &nbsp;</p>","stem":"<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>","answerOptions":[{"id":"a57d7686-92df-46d2-9f6c-a69b4da14c70","content":"<p>extensive: a&nbsp;</p>"},{"id":"d73f6575-64ca-49ef-938d-0233b96c79e9","content":"<p>extensive; a</p>"},{"id":"22dbf2e5-6e7d-4e54-9a9e-a237bb07b861","content":"<p>extensive, it was a &nbsp;</p>"},{"id":"a8cdb39e-97da-4db2-9afd-fb459d19599b","content":"<p>extensive. A&nbsp;</p>"}],"keys":["a57d7686-92df-46d2-9f6c-a69b4da14c70"],"correct_answer":["A"],"rationale":"<p>Choice A is the best answer. The convention being tested is the use of a colon within a sentence. In this choice, the colon is correctly used to introduce the following explanation of what the Patriot cause had grown into by 1774.</p><p>Choice B is incorrect because a semicolon can&rsquo;t be used in this way to join the main clause (\"what&hellip;extensive\") and the supplementary element  (\"a network&hellip;Congress\"). A semicolon is conventionally used to join two main clauses, whereas a colon is conventionally used to introduce an element that explains or amplifies the information in the preceding clause, making the colon the better choice in this context. Choice C is incorrect because it results in a comma splice. The addition of the pronoun and verb \"it was\" forms the start of a new main clause in the sentence, and a comma can&rsquo;t be used in this way to mark the boundary between two main clauses. Choice D is incorrect because it results in a rhetorically unacceptable sentence fragment beginning with \"a network.\"</p>","parenttemplatename":null,"parenttemplateid":null,"templateclusterid":null,"templateclustername":null,"origin":null,"position":null,"createDate":1730147323050,"updateDate":1730147323050}$SATQ$::jsonb, 1730147323050, 1730147323050),
    ($SATQ$ea0aa676$SATQ$, $SATQ$da72d380-645c-41e2-b520-90d8e8d60daf$SATQ$::uuid, $SATQ$9d79e5e0-1702-4633-8f1d-89d87f03fcfd$SATQ$::uuid, NULL, $SATQ$qbank$SATQ$, $SATQ$SAT$SATQ$, 1, $SATQ$Reading and Writing$SATQ$, $SATQ$Standard English Conventions$SATQ$, $SATQ$SEC$SATQ$, $SATQ$FSS$SATQ$, $SATQ$Form, Structure, and Sense$SATQ$, $SATQ$H$SATQ$, 7, $SATQ$mcq$SATQ$, $SATQ$<p>In the 1970s, Janaki Ammal, a prominent botanist, emerged as a powerful voice in India&rsquo;s environmental conservation movement. Her exhaustive chromosomal survey of plants in Silent Valley, a pristine tropical forest in Kerala, India, that is home to nearly 1,000 species of native flora (many of which are endangered), <span aria-hidden="true">______</span><span class="sr-only">blank</span> instrumental in the government&rsquo;s decision to preserve the forest.</p>$SATQ$, $SATQ$<p>Which choice completes the text so that it conforms to the conventions of Standard English?</p>$SATQ$, $SATQ$[{"id":"652e2cbc-4626-429a-ab7f-77d6e24a54a6","content":"<p>are</p>"},{"id":"e971b7dd-ff23-4768-b98b-180a74b43824","content":"<p>were</p>"},{"id":"93c6c130-433d-437e-8ece-dd251259825c","content":"<p>have been</p>"},{"id":"bbbd30cf-c9e4-4982-b5f5-4b0cc0b5bc31","content":"<p>was</p>"}]$SATQ$::jsonb, $SATQ$["D"]$SATQ$::jsonb, $SATQ$["bbbd30cf-c9e4-4982-b5f5-4b0cc0b5bc31"]$SATQ$::jsonb, $SATQ$<p>Choice D is the best answer. The subject "survey" is singular, and so is the verb "was."</p><p>Choice A is incorrect. The subject "survey" is singular, but the verb "are" is plural. Choice B is incorrect. The subject "survey" is singular, but the verb "were" is plural. Choice C is incorrect. The subject "survey" is singular, but the verb "have been" is plural.</p>$SATQ$, false, 0, $SATQ$OSP-KA-FSS-H008$SATQ$, $SATQ$$SATQ$, $SATQ$48ee3247-84e3-46e9-8b62-c8fcdbb70a97$SATQ$::uuid, $SATQ$$SATQ$, $SATQ$proteus$SATQ$, $SATQ$0$SATQ$, NULL, NULL, $SATQ${"questionId":"ea0aa676","external_id":"da72d380-645c-41e2-b520-90d8e8d60daf","